WITH base AS (SELECT id, customer_id, account_type, balance, opened_date, status, CASE WHEN status IN ('CLOSED', 'OPEN') THEN 'Priority' ELSE 'Other' END AS status_group, COALESCE(status, 'OTHER') AS resolved_status FROM accounts WHERE opened_date >= TO_DATE('2023-06-05')), eligible AS (SELECT s.* FROM base s WHERE EXISTS (SELECT 1 FROM transactions x WHERE x.account_id = s.id AND x.txn_time <= s.opened_date)), valid AS (SELECT *, DATE_FORMAT(opened_date, 'yyyy-MM-dd') AS opened_date_label, ROUND(balance, 0) AS balance_rounded FROM eligible WHERE YEAR(opened_date) >= 2024), latest_match AS (SELECT s.id, s.account_type, s.balance, s.opened_date, s.status, s.status_group, s.resolved_status, s.opened_date_label, top1.txn_type FROM valid s LEFT JOIN LATERAL (SELECT c.txn_type FROM transactions c WHERE c.account_id = s.id AND c.txn_time <= s.opened_date ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) top1 ON TRUE), scored AS (SELECT id, status, status_group, opened_date_label, LEAD(balance) OVER (PARTITION BY account_type ORDER BY balance, id) AS next_balance, ROW_NUMBER() OVER (PARTITION BY account_type ORDER BY balance, id) AS event_seq, MIN(balance) OVER (PARTITION BY status) AS status_min_balance FROM latest_match WHERE balance > 58000), kept AS (SELECT s.* FROM scored s WHERE NOT EXISTS (SELECT 1 FROM transactions x WHERE x.account_id = s.id AND HOUR(x.txn_time) BETWEEN 8 AND 11)) SELECT id, status, opened_date_label, next_balance, event_seq, status_min_balance FROM kept ORDER BY next_balance NULLS FIRST
